let currentFontSize=Number(localStorage.getItem('ca-font-size'))||16;
let readerOn=false, announcementIndex=0, bannerIndex=0, tourIndex=0, storyIndex=0;
let currentLanguage=localStorage.getItem('ca-language')||'en';

function t(key){return (translations[currentLanguage]&&translations[currentLanguage][key])||translations.en[key]||key;}
function saveSetting(key,value){try{localStorage.setItem(key,String(value));}catch(e){}}
function esc(s){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}

function skipToMain(){const main=document.getElementById('mainContent');if(main){main.focus({preventScroll:true});main.scrollIntoView({behavior:'smooth',block:'start'});}}
function toggleAccessibility(){const panel=document.getElementById('accessibilityPanel');if(!panel)return;const open=panel.classList.toggle('hidden')===false;document.querySelector('.accessibility-trigger')?.setAttribute('aria-expanded',String(open));document.getElementById('accessChevron')?.classList.toggle('rotate',open);if(open)document.querySelector('#accessibilityPanel button')?.focus();}
function updateFontDots(){document.querySelectorAll('.font-dot').forEach(x=>x.classList.remove('active'));if(currentFontSize<=14)document.querySelector('.dot-small')?.classList.add('active');else if(currentFontSize<=17)document.querySelector('.dot-normal')?.classList.add('active');else document.querySelector('.dot-large')?.classList.add('active');}
function changeFontSize(delta){setFontSize(Math.min(24,Math.max(13,currentFontSize+delta)));}
function setFontSize(value){currentFontSize=Number(value)||16;document.documentElement.style.fontSize=currentFontSize+'px';saveSetting('ca-font-size',currentFontSize);updateFontDots();}
function resetFontSize(){setFontSize(16);}
function updateSaturationDots(value){document.querySelectorAll('.sat-dot').forEach(x=>x.classList.remove('active'));const map={'.55':'.sat-low','.8':'.sat-mid','1':'.sat-normal','1.35':'.sat-high','1.6':'.sat-max'};document.querySelector(map[String(value)])?.classList.add('active');}
function setSaturation(value){value=Number(value);document.body.classList.remove('saturation-low','saturation-mid','saturation-high','saturation-max');if(value===.55)document.body.classList.add('saturation-low');else if(value===.8)document.body.classList.add('saturation-mid');else if(value===1.35)document.body.classList.add('saturation-high');else if(value===1.6)document.body.classList.add('saturation-max');updateSaturationDots(value);saveSetting('ca-saturation',value);}
function toggleReader(){readerOn=!readerOn;const state=document.getElementById('readerState'),btn=document.getElementById('readerToggle');if(state)state.textContent=readerOn?t('on'):t('off');if(btn)btn.setAttribute('aria-pressed',String(readerOn));if(readerOn){speakText(document.querySelector('.page-view:not(.hidden)')?.innerText||t('brand_name'));}else if('speechSynthesis'in window)window.speechSynthesis.cancel();}
function speakText(text){if(!('speechSynthesis'in window)){alert(currentLanguage==='hi'?'यह ब्राउज़र बोलकर पढ़ने की सुविधा का समर्थन नहीं करता।':currentLanguage==='mr'?'हा ब्राउझर बोलून वाचण्याच्या सुविधेला समर्थन देत नाही.':'This browser does not support spoken reading.');return;}window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(String(text).replace(/\s+/g,' ').slice(0,4500));u.lang=currentLanguage==='hi'?'hi-IN':currentLanguage==='mr'?'mr-IN':'en-IN';u.rate=.9;u.pitch=1;window.speechSynthesis.speak(u);}
function toggleDarkMode(){const on=document.body.classList.toggle('dark-mode');saveSetting('ca-dark-mode',on);updateAccessibilityStates();}
function toggleSimpleView(){const on=document.body.classList.toggle('simple-view');saveSetting('ca-simple-view',on);updateAccessibilityStates();}
function updateAccessibilityStates(){const dark=document.body.classList.contains('dark-mode'),simple=document.body.classList.contains('simple-view'),contrast=document.body.classList.contains('high-contrast'),invert=document.documentElement.classList.contains('invert-mode');const ds=document.getElementById('darkModeState'),ss=document.getElementById('simpleViewState'),cs=document.getElementById('contrastState'),is=document.getElementById('invertState'),db=document.getElementById('darkModeToggle'),sb=document.getElementById('simpleViewToggle'),cb=document.getElementById('contrastToggle'),ib=document.getElementById('invertToggle');if(ds)ds.textContent=dark?t('on'):t('off');if(ss)ss.textContent=simple?t('on'):t('off');if(cs)cs.textContent=contrast?t('on'):t('off');if(is)is.textContent=invert?t('on'):t('off');if(db)db.setAttribute('aria-pressed',String(dark));if(sb)sb.setAttribute('aria-pressed',String(simple));if(cb)cb.setAttribute('aria-pressed',String(contrast));if(ib)ib.setAttribute('aria-pressed',String(invert));const rs=document.getElementById('readerState'),rb=document.getElementById('readerToggle');if(rs)rs.textContent=readerOn?t('on'):t('off');if(rb)rb.setAttribute('aria-pressed',String(readerOn));}
function toggleHighContrast(){document.body.classList.toggle('high-contrast');saveSetting('ca-high-contrast',document.body.classList.contains('high-contrast'));updateAccessibilityStates();}
function toggleInvert(){document.documentElement.classList.toggle('invert-mode');saveSetting('ca-invert',document.documentElement.classList.contains('invert-mode'));updateAccessibilityStates();}
function resetAccessibility(){setFontSize(16);setSaturation(1);document.body.classList.remove('high-contrast','saturation-low','saturation-mid','saturation-high','saturation-max','dark-mode','simple-view');document.documentElement.classList.remove('invert-mode');saveSetting('ca-high-contrast','false');saveSetting('ca-invert','false');saveSetting('ca-dark-mode','false');saveSetting('ca-simple-view','false');readerOn=false;if('speechSynthesis'in window)window.speechSynthesis.cancel();updateAccessibilityStates();}

