function renderServiceCategoryOptions(){const select=document.getElementById('filterCategory');if(!select)return;const labels={en:{all:'All categories',identity:'Identity & Tax',transport:'Transport & Travel',education:'Student & Education',welfare:'Welfare & Certificates',digital:'Digital Government',employment:'Employment & Career'},hi:{all:'सभी श्रेणियाँ',identity:'पहचान और कर',transport:'परिवहन और यात्रा',education:'छात्र और शिक्षा',welfare:'कल्याण और प्रमाणपत्र',digital:'डिजिटल सरकारी सेवाएँ',employment:'रोजगार और करियर'},mr:{all:'सर्व श्रेणी',identity:'ओळख आणि कर',transport:'वाहतूक आणि प्रवास',education:'विद्यार्थी आणि शिक्षण',welfare:'कल्याण आणि प्रमाणपत्रे',digital:'डिजिटल सरकारी सेवा',employment:'रोजगार आणि करिअर'}}[currentLanguage]||{};const cats=['all',...Array.from(new Set(serviceCatalog.map(x=>x.category)))];select.innerHTML=cats.map(c=>`<option value="${c}">${labels[c]||c}</option>`).join('');}
function renderServices(){const c=document.getElementById('servicesListContainer');if(!c)return;renderServiceCategoryOptions();c.innerHTML=serviceCatalog.map(d=>{const l=localizedService(d);return `<article class="service-entry" data-keywords="${esc(d.keywords)}" data-role="${esc(d.role)}" data-category="${d.category}" data-difficulty="${d.difficulty}"><div class="service-row-icon ${d.tone}"><i class="fa-solid ${d.icon}"></i></div><div class="service-row-content"><div class="service-title"><h2>${esc(l.title)}</h2><span class="difficulty ${d.difficulty}">${esc(t(d.difficulty))}</span></div><p>${esc(l.desc)}</p><div class="service-meta"><span><i class="fa-solid fa-file"></i> ${esc(t('documents'))}</span><span><i class="fa-solid fa-list-check"></i> ${esc(t('steps'))}</span><span><i class="fa-solid fa-link"></i> ${esc(t('official_link'))}</span></div></div><button onclick="openGuide('${d.key}')" class="primary-button-small"><span>${esc(t('view_guide'))}</span> <i class="fa-solid fa-arrow-right"></i></button></article>`;}).join('');filterServicesList();}
function filterServicesList(){const input=document.getElementById('serviceSearchInput'),cat=document.getElementById('filterCategory'),diff=document.getElementById('filterDifficulty');if(!input||!cat||!diff)return;const q=input.value.toLowerCase().trim();let visible=0;document.querySelectorAll('.service-entry').forEach(e=>{const hay=(e.dataset.keywords+' '+e.dataset.role+' '+e.innerText).toLowerCase();const ok=hay.includes(q)&&(cat.value==='all'||e.dataset.category===cat.value)&&(diff.value==='all'||e.dataset.difficulty===diff.value);e.style.display=ok?'flex':'none';if(ok)visible++;});document.getElementById('noServices')?.classList.toggle('hidden',visible!==0);}

